class _RecordDialog extends StatefulWidget {
 final bool product; final Map<String,Object?>? record;
 const _RecordDialog({required this.product,this.record});
 @override State<_RecordDialog> createState()=>_RecordDialogState();
}
class _RecordDialogState extends State<_RecordDialog> {
 late final List<TextEditingController> cs;
 @override void initState(){super.initState();final keys=widget.product?['code','name','price','qty','gst','cost','category','barcode']:['name','phone','address'];cs=keys.map((k)=>TextEditingController(text:widget.record?[k]?.toString()??'')).toList();}
 @override void dispose(){for(final c in cs){c.dispose();}super.dispose();}
 Widget field(String label,TextEditingController c,{bool numeric=false})=>Padding(padding:const EdgeInsets.only(bottom:14),child:TextField(controller:c,keyboardType:numeric?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,decoration:InputDecoration(labelText:label,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14)))));
 @override Widget build(BuildContext context)=>AlertDialog(
 title:Text(widget.record==null?(widget.product?'Add product':'Add customer'):(widget.product?'Edit product':'Edit customer')),
 content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:List.generate(cs.length,(i)=>field((widget.product?['Item code','Product name','Price before GST','Stock quantity','GST %','Purchase price (optional)','Category','Barcode']:['Name','Phone','Address'])[i],cs[i],numeric:widget.product&&i>=2&&i<=5)))),
 actions:[TextButton(onPressed:()=>Navigator.of(context).pop(),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.of(context).pop(cs.map((c)=>c.text.trim()).toList()),child:const Text('Save'))]);
}
